const t = ($json.mensagem_normalizada || "");
let reply = "Posso te ajudar com entrega, pagamento, compra pelo site, produtos e atendimento humano. Sobre qual tema voce quer falar?";

if (["belem", "para", "fora de sp", "outro estado", "norte", "nordeste", "rio de janeiro", "minas gerais"].some(p => t.includes(p))) {
  reply = "No momento, realizamos entregas apenas em Sao Paulo. Se quiser, posso te direcionar para um atendente no WhatsApp: https://wa.me/55NUMERO";
} else if (["entrega", "frete", "envio", "receber", "prazo", "sp", "sao paulo"].some(p => t.includes(p))) {
  reply = "Realizamos entregas para toda Sao Paulo. Para consultar valores, prazos e finalizar a compra, voce pode acessar nosso site.";
} else if (["erro", "falhou", "problema", "cobrou", "nao consegui pagar", "pagamento nao"].some(p => t.includes(p))) {
  reply = "Nesse caso, vou te direcionar para um atendente pelo WhatsApp para verificarem melhor: https://wa.me/55NUMERO";
} else if (["pagamento", "pagar", "pix", "cartao", "boleto", "parcelamento", "parcela"].some(p => t.includes(p))) {
  reply = "Aceitamos pagamentos por cartao, Pix e Boleto, entretanto nao parcelamos o valor. A realizacao do pedido e pagamento e feita diretamente pelo site.";
} else if (["comprar", "compra", "quero comprar", "link", "site", "pedido"].some(p => t.includes(p))) {
  reply = "A compra e feita diretamente pelo nosso site. Voce pode escolher os produtos e finalizar o pagamento por la: https://metasuplementosoficial.lojavirtualnuvem.com.br";
} else if (["whey", "creatina", "vitamina", "suplemento", "pre-treino", "hipercalorico"].some(p => t.includes(p))) {
  reply = "Temos opcoes de whey, creatina, vitaminas e outros suplementos no site. Para ver disponibilidade e valores, consulte: https://metasuplementosoficial.lojavirtualnuvem.com.br";
} else if (["personal", "nutricionista", "nutri", "acompanhamento", "consultoria"].some(p => t.includes(p))) {
  reply = "Para falar sobre acompanhamento com personal ou nutricionista, vou te direcionar para o WhatsApp: https://wa.me/55NUMERO";
}

return [{ json: { ...$json, reply } }];
